  en.forEach(e => { const co = MC.co(e.cohort), m = MC.mc(co.mc); e.modules.forEach((x, i) => mods.push([MC.mcName(m.id), co.name, m.modules[i][0], x[0], x[1] || '–', x[0] === 'Achieved' ? 'Module badge' : '–'])); });
